def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()
def unit(name):
 r=subprocess.run(['systemctl','show',name,'--property=MainPID,ActiveState,SubState,Job,Restart,KillMode,SendSIGKILL,TimeoutStopUSec'],capture_output=True,text=True,timeout=4)
 assert r.returncode==0
 return dict(x.split('=',1) for x in r.stdout.splitlines() if '=' in x)
def sync(path):
 fd=os.open(str(path),os.O_RDONLY|os.O_DIRECTORY)
 try:os.fsync(fd)
 finally:os.close(fd)
def create(path,data,mode=0o600,uid=None,gid=None):
 fd=os.open(str(path),os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,mode)
 with os.fdopen(fd,'wb') as file:
  file.write(data);file.flush();os.fsync(file.fileno())
 if uid is not None:os.chown(path,uid,gid)
 sync(path.parent)
