rows=[]
for entry in E['payload']:
 path=aura/entry['path'];assert path.resolve()==path and not path.is_symlink()
 old=path.read_bytes();assert hashlib.sha256(old).hexdigest()==entry['before_sha256']==pins[entry['path']]
